import React, { useState, useRef, useEffect } from 'react';
import { useDropzone } from 'react-dropzone';
import { useTranslation } from 'react-i18next';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { STLLoader } from 'three/examples/jsm/loaders/STLLoader.js';
import { ThreeMFLoader } from 'three/examples/jsm/loaders/3MFLoader.js';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import {
  UploadCloud,
  CheckCircle2,
  RotateCw,
  Box,
  Wand2,
  RotateCcw,
  Sparkles,
  SlidersHorizontal,
  X,
  Compass
} from 'lucide-react';
import { findOptimalOrientation } from '../services/stlOptimizer';

// Put the object's lowest vertex exactly on the build plate (Z=0).
// `precise = true` is required: the default Box3 only transforms the 8 corners of the
// local bounding box, which overestimates the extent once the model is rotated
// and makes the object float above (or sink below) the plate.
function groundOnPlate(pivot) {
  pivot.position.set(0, 0, 0);
  pivot.updateMatrixWorld(true);
  const bbox = new THREE.Box3().setFromObject(pivot, true);
  pivot.position.set(0, 0, -bbox.min.z);
  pivot.updateMatrixWorld(true);
  return new THREE.Box3().setFromObject(pivot, true);
}

const isStlFile = (f) => !!f && /\.stl$/i.test(f.name);

// Parse STL or 3MF into a single position-only BufferGeometry (mm, Z-up).
function parseModelGeometry(file, buffer) {
  if (isStlFile(file)) {
    return new STLLoader().parse(buffer);
  }
  const group = new ThreeMFLoader().parse(buffer);
  group.updateMatrixWorld(true);
  const parts = [];
  group.traverse((obj) => {
    if (!obj.isMesh || !obj.geometry) return;
    let g = obj.geometry.index ? obj.geometry.toNonIndexed() : obj.geometry.clone();
    g.applyMatrix4(obj.matrixWorld);
    // Keep only positions so parts with different attributes can be merged
    const clean = new THREE.BufferGeometry();
    clean.setAttribute('position', g.getAttribute('position'));
    parts.push(clean);
  });
  if (parts.length === 0) throw new Error('No mesh found in 3MF file');
  return parts.length === 1 ? parts[0] : mergeGeometries(parts);
}

// Procedural textured PEI sheet (fine speckle) used for the bed surface.
function createPeiTexture(repeat) {
  const size = 512;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#2b2f36';
  ctx.fillRect(0, 0, size, size);
  const img = ctx.getImageData(0, 0, size, size);
  for (let i = 0; i < img.data.length; i += 4) {
    const n = (Math.random() - 0.5) * 38;
    img.data[i] += n;
    img.data[i + 1] += n;
    img.data[i + 2] += n * 1.05;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat, repeat);
  tex.anisotropy = 8;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export default function StudioModelViewer({
  file,
  onFileAccepted,
  printerBedSize,
  rotateX,
  rotateY,
  rotateZ,
  onChangeRotateX,
  onChangeRotateY,
  onChangeRotateZ,
  onResetRotation,
  onModelDimsChange,
  loading
}) {
  const { t } = useTranslation();
  const [showAnglesPanel, setShowAnglesPanel] = useState(true);
  const [optimizing, setOptimizing] = useState(false);
  const [modelDims, setModelDims] = useState(null);
  // Bumped every time a fresh WebGL scene is built, so the model gets (re)added to it
  const [sceneVersion, setSceneVersion] = useState(0);
  const hasFile = !!file;
  const canRotate = isStlFile(file); // backend (admesh) only rotates STL

  const containerRef = useRef(null);
  const sceneRef = useRef(null);
  const cameraRef = useRef(null);
  const rendererRef = useRef(null);
  const orbitControlsRef = useRef(null);
  const pivotGroupRef = useRef(null);
  const meshRef = useRef(null);

  const bedX = printerBedSize ? printerBedSize[0] : 220;
  const bedY = printerBedSize ? printerBedSize[1] : 220;
  const bedZ = printerBedSize ? printerBedSize[2] : 250;

  const {
    getRootProps,
    getInputProps,
    isDragActive
  } = useDropzone({
    maxFiles: 1,
    maxSize: 104857600, // 100 MB
    multiple: false,
    onDropAccepted: onFileAccepted
  });

  // Size of the model as it sits on the plate (after rotation), reported to the parent
  const onModelDimsChangeRef = useRef(onModelDimsChange);
  onModelDimsChangeRef.current = onModelDimsChange;
  const reportOrientedDims = (bbox) => {
    if (!onModelDimsChangeRef.current) return;
    const size = bbox.getSize(new THREE.Vector3());
    onModelDimsChangeRef.current({ x: size.x, y: size.y, z: size.z });
  };

  // Dynamic automatic orientation calculator
  const handleAutoOrient = async () => {
    if (!file || optimizing) return;
    setOptimizing(true);
    try {
      const best = await findOptimalOrientation(file);
      onChangeRotateX(best.rx);
      onChangeRotateY(best.ry);
      onChangeRotateZ(best.rz);
    } catch (err) {
      console.error('Auto orientation error', err);
    } finally {
      setOptimizing(false);
    }
  };

  // Quick 90 deg steps
  const stepRotate = (axis, delta) => {
    if (axis === 'x') onChangeRotateX((rotateX + delta + 360) % 360);
    if (axis === 'y') onChangeRotateY((rotateY + delta + 360) % 360);
    if (axis === 'z') onChangeRotateZ((rotateZ + delta + 360) % 360);
  };

  // Helper for manual numeric input: ensures in range [0, 360]
  const handleManualAngleChange = (axis, val) => {
    const num = Number(val);
    if (isNaN(num)) return;
    const clamped = Math.max(0, Math.min(360, Math.round(num)));
    if (axis === 'x') onChangeRotateX(clamped);
    if (axis === 'y') onChangeRotateY(clamped);
    if (axis === 'z') onChangeRotateZ(clamped);
  };

  // 1. Initialize Three.js scene, camera, lights, and standard OrbitControls
  useEffect(() => {
    // The canvas container only exists once a file is loaded
    const container = containerRef.current;
    if (!container) return;

    const width = container.clientWidth || 600;
    const height = container.clientHeight || 500;

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color('#f8fafc');
    sceneRef.current = scene;

    // Camera (Z-up orientation standard in 3D printing)
    const camera = new THREE.PerspectiveCamera(45, width / height, 1, 3000);
    camera.up.set(0, 0, 1);
    camera.position.set(bedX * 1.3, -bedY * 1.3, Math.max(bedX, bedY) * 1.1);
    camera.lookAt(0, 0, 40);
    cameraRef.current = camera;

    // WebGL Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    container.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Standard CAD Camera OrbitControls:
    // - LEFT CLICK: Orbits camera view (MOUSE.ROTATE)
    // - RIGHT CLICK: Pans/translates camera view (MOUSE.PAN)
    // - MIDDLE CLICK / WHEEL: Zooms (MOUSE.DOLLY)
    const orbit = new OrbitControls(camera, renderer.domElement);
    orbit.target.set(0, 0, 40);
    orbit.enableDamping = true;
    orbit.dampingFactor = 0.08;
    orbit.mouseButtons = {
      LEFT: THREE.MOUSE.ROTATE,
      MIDDLE: THREE.MOUSE.DOLLY,
      RIGHT: THREE.MOUSE.PAN
    };
    orbitControlsRef.current = orbit;

    // Ambient and directional lighting (with proper shadow bias to eliminate flickering acne)
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.9);
    scene.add(ambientLight);

    const dirLight1 = new THREE.DirectionalLight(0xffffff, 0.85);
    dirLight1.position.set(bedX * 1.5, -bedY * 1.5, bedZ * 2);
    dirLight1.castShadow = true;
    dirLight1.shadow.bias = -0.0005;
    dirLight1.shadow.normalBias = 0.05;
    dirLight1.shadow.mapSize.width = 2048;
    dirLight1.shadow.mapSize.height = 2048;
    scene.add(dirLight1);

    const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.4);
    dirLight2.position.set(-bedX, bedY, bedZ * 1.5);
    scene.add(dirLight2);

    // Realistic printer bed: aluminium heatbed + textured PEI sheet + grid on top
    const baseT = 8;   // heatbed thickness (mm)
    const sheetT = 1.6; // PEI sheet thickness (mm)
    const frameMat = new THREE.MeshStandardMaterial({ color: 0x9aa3ad, metalness: 0.85, roughness: 0.35 });
    const heatbed = new THREE.Mesh(new THREE.BoxGeometry(bedX + 8, bedY + 8, baseT), frameMat);
    heatbed.position.set(0, 0, -sheetT - baseT / 2);
    heatbed.receiveShadow = true;
    scene.add(heatbed);

    const peiTex = createPeiTexture(Math.max(bedX, bedY) / 40);
    const peiTop = new THREE.MeshStandardMaterial({
      map: peiTex,
      bumpMap: peiTex,
      bumpScale: 0.6,
      roughness: 0.62,
      metalness: 0.12
    });
    const peiSide = new THREE.MeshStandardMaterial({ color: 0x1c1f24, roughness: 0.7, metalness: 0.2 });
    // BoxGeometry face order: +x, -x, +y, -y, +z (top), -z
    const sheet = new THREE.Mesh(
      new THREE.BoxGeometry(bedX, bedY, sheetT),
      [peiSide, peiSide, peiSide, peiSide, peiTop, peiSide]
    );
    sheet.position.set(0, 0, -sheetT / 2);
    sheet.receiveShadow = true;
    scene.add(sheet);

    // Grid lines on the sheet: minor every 10 mm, major every 50 mm
    const gridPts = [];
    const majorPts = [];
    for (let x = -bedX / 2; x <= bedX / 2 + 0.01; x += 10) {
      (Math.round(x - -bedX / 2) % 50 === 0 ? majorPts : gridPts).push(x, -bedY / 2, 0, x, bedY / 2, 0);
    }
    for (let y = -bedY / 2; y <= bedY / 2 + 0.01; y += 10) {
      (Math.round(y - -bedY / 2) % 50 === 0 ? majorPts : gridPts).push(-bedX / 2, y, 0, bedX / 2, y, 0);
    }
    const makeLines = (pts, color, opacity) => {
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
      const m = new THREE.LineBasicMaterial({ color, transparent: true, opacity, depthWrite: false });
      const lines = new THREE.LineSegments(g, m);
      lines.position.z = 0.05;
      lines.renderOrder = 1;
      scene.add(lines);
    };
    makeLines(gridPts, 0xcbd5e1, 0.14);
    makeLines(majorPts, 0x38bdf8, 0.4);

    // Soft contact shadow on the surface under the printer
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(bedX * 4, bedY * 4), new THREE.ShadowMaterial({ opacity: 0.18 }));
    floor.position.z = -sheetT - baseT - 0.5;
    floor.receiveShadow = true;
    scene.add(floor);

    // Shadow frustum must cover the whole bed
    const ext = Math.max(bedX, bedY) * 0.9;
    dirLight1.shadow.camera.left = -ext;
    dirLight1.shadow.camera.right = ext;
    dirLight1.shadow.camera.top = ext;
    dirLight1.shadow.camera.bottom = -ext;
    dirLight1.shadow.camera.near = 1;
    dirLight1.shadow.camera.far = Math.max(bedX, bedY, bedZ) * 6;
    dirLight1.shadow.camera.updateProjectionMatrix();

    // Animation render loop
    let animationFrameId;
    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);
      orbit.update();
      renderer.render(scene, camera);
    };
    animate();
    setSceneVersion((v) => v + 1);

    // Resize observer
    const handleResize = () => {
      if (!container || !renderer || !camera) return;
      const w = container.clientWidth;
      const h = container.clientHeight;
      if (w > 0 && h > 0) {
        camera.aspect = w / h;
        camera.updateProjectionMatrix();
        renderer.setSize(w, h);
      }
    };
    window.addEventListener('resize', handleResize);

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
      orbit.dispose();
      renderer.dispose();
      // Old scene is gone: forget the model that lived in it
      sceneRef.current = null;
      pivotGroupRef.current = null;
      meshRef.current = null;
      if (container && renderer.domElement) {
        container.removeChild(renderer.domElement);
      }
    };
  }, [bedX, bedY, bedZ, hasFile]);

  // Keep latest rotation values in refs for initialization
  const rotateXRef = useRef(rotateX);
  const rotateYRef = useRef(rotateY);
  const rotateZRef = useRef(rotateZ);
  useEffect(() => {
    rotateXRef.current = rotateX;
    rotateYRef.current = rotateY;
    rotateZRef.current = rotateZ;
  }, [rotateX, rotateY, rotateZ]);

  // 2. Load STL file geometry when `file` changes
  useEffect(() => {
    if (!file) {
      if (onModelDimsChangeRef.current) onModelDimsChangeRef.current(null);
      return;
    }
    if (!sceneRef.current) return;

    let isCancelled = false;

    file.arrayBuffer().then((buffer) => {
      if (isCancelled) return;
      const geometry = parseModelGeometry(file, buffer);
      geometry.computeVertexNormals();
      geometry.center(); // Center geometry around its origin (0, 0, 0)

      geometry.computeBoundingBox();
      const bbox = geometry.boundingBox;
      const width = bbox.max.x - bbox.min.x;
      const length = bbox.max.y - bbox.min.y;
      const height = bbox.max.z - bbox.min.z;
      const sphere = new THREE.Sphere();
      geometry.computeBoundingSphere();
      sphere.copy(geometry.boundingSphere);
      const boundingRadius = sphere.radius;

      setModelDims({ width, length, height, boundingRadius });

      // Clean up previous mesh / pivot
      if (pivotGroupRef.current) {
        sceneRef.current.remove(pivotGroupRef.current);
        if (meshRef.current && meshRef.current.geometry) {
          meshRef.current.geometry.dispose();
          meshRef.current.material.dispose();
        }
      }

      // Create new technical slicer blue Mesh
      const material = new THREE.MeshStandardMaterial({
        color: 0x0284c7,
        metalness: 0.15,
        roughness: 0.45
      });
      const mesh = new THREE.Mesh(geometry, material);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      meshRef.current = mesh;

      const pivotGroup = new THREE.Group();
      pivotGroup.add(mesh);

      // Set initial orientation
      pivotGroup.position.set(0, 0, 0);
      pivotGroup.rotation.set(
        THREE.MathUtils.degToRad(rotateXRef.current),
        THREE.MathUtils.degToRad(rotateYRef.current),
        THREE.MathUtils.degToRad(rotateZRef.current),
        'XYZ'
      );

      // Keep bottom facet resting exactly on the build plate (Z=0)
      reportOrientedDims(groundOnPlate(pivotGroup));

      sceneRef.current.add(pivotGroup);
      pivotGroupRef.current = pivotGroup;

      // Frame camera to nicely view the loaded model
      if (cameraRef.current && orbitControlsRef.current) {
        const cameraDist = Math.max(boundingRadius * 3.5, 160);
        cameraRef.current.position.set(cameraDist * 0.9, -cameraDist * 0.9, cameraDist * 0.7);
        const centerZ = height / 2;
        orbitControlsRef.current.target.set(0, 0, centerZ);
        cameraRef.current.lookAt(0, 0, centerZ);
        orbitControlsRef.current.update();
      }
    }).catch((err) => {
      console.error('Failed to parse model file', err);
    });

    return () => {
      isCancelled = true;
    };
  }, [file, sceneVersion]);

  // 3. Update 3D mesh rotation when rotateX, rotateY, rotateZ props change
  useEffect(() => {
    const pivot = pivotGroupRef.current;
    if (!pivot) return;

    pivot.rotation.set(
      THREE.MathUtils.degToRad(rotateX),
      THREE.MathUtils.degToRad(rotateY),
      THREE.MathUtils.degToRad(rotateZ),
      'XYZ'
    );

    // Keep model bottom grounded on the build plate (Z=0)
    const groundedBbox = groundOnPlate(pivot);
    reportOrientedDims(groundedBbox);

    // Update orbitControls target to smoothly focus on the grounded model center
    if (orbitControlsRef.current) {
      const center = new THREE.Vector3();
      groundedBbox.getCenter(center);
      orbitControlsRef.current.target.set(0, 0, center.z);
    }
  }, [rotateX, rotateY, rotateZ]);

  return (
    <div className="studio-card p-3 sm:p-4 flex flex-col flex-1 h-full min-h-[520px] lg:min-h-full">
      {/* Viewport Top Bar */}
      <div className="flex items-center justify-between pb-2.5 mb-2 border-b border-slate-100 flex-wrap gap-2">
        <div className="flex items-center space-x-2">
          {file ? (
            <span className="inline-flex items-center space-x-1 px-2 py-0.5 rounded-full text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200">
              <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" />
              <span>{t('modelLoaded')}</span>
            </span>
          ) : (
            <span className="inline-flex items-center space-x-1 px-2 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-600">
              <Box className="w-3.5 h-3.5 text-slate-400" />
              <span>{t('noModelLoaded')}</span>
            </span>
          )}

          {file && (
            <span className="text-xs font-bold text-slate-800 max-w-[280px] truncate" title={file.name}>
              {file.name}
            </span>
          )}
        </div>

        <div className="flex items-center space-x-3 text-xs">
          {modelDims && (
            <span className="text-slate-500 font-mono hidden sm:inline">
              Modèle: <strong className="text-slate-700 font-semibold">{Math.round(modelDims.width)} × {Math.round(modelDims.length)} × {Math.round(modelDims.height)} mm</strong>
            </span>
          )}
          <span className="text-slate-500 font-mono">
            Bed: <strong className="text-slate-700 font-semibold">{bedX} × {bedY} × {bedZ} mm</strong>
          </span>
          {file && (
            <div {...getRootProps()} className="inline-block">
              <input {...getInputProps()} />
              <button
                type="button"
                className="inline-flex items-center space-x-1 text-xs font-medium text-primary-600 hover:text-primary-700 hover:underline cursor-pointer"
              >
                <RotateCw className="w-3 h-3" />
                <span>{t('changeModel')}</span>
              </button>
            </div>
          )}
        </div>
      </div>

      {/* 3D Viewport Area */}
      <div
        className="relative flex-1 w-full min-h-[460px] rounded-xl bg-gradient-to-b from-slate-100 to-slate-200/60 border border-slate-200 overflow-hidden flex items-center justify-center select-none"
      >
        {!file ? (
          <div
            {...getRootProps({
              className: `w-full h-full flex flex-col items-center justify-center p-8 text-center cursor-pointer transition-all border-2 border-dashed ${
                isDragActive
                  ? 'border-primary-500 bg-primary-50/50'
                  : 'border-slate-300 hover:border-slate-400 bg-white/40'
              }`
            })}
          >
            <input {...getInputProps()} />
            <div className="w-16 h-16 rounded-2xl bg-white shadow-sm border border-slate-200 flex items-center justify-center text-primary-600 mb-3 group-hover:scale-105 transition-transform">
              <UploadCloud className="w-8 h-8 text-primary-600" />
            </div>
            <h3 className="text-sm font-bold text-slate-800 mb-1">
              {t('dragNDropTitle')}
            </h3>
            <p className="text-xs text-slate-500 mb-4 max-w-sm">
              {t('dragNDropSubtitle')}
            </p>
            <button
              type="button"
              className="px-4 py-2 rounded-lg text-xs font-semibold bg-white text-slate-800 border border-slate-300 hover:bg-slate-50 shadow-xs"
            >
              {t('browseFiles')}
            </button>
          </div>
        ) : (
          <div className="w-full h-full absolute inset-0">
            {/* Slicer Vertical Tool Palette (Top-left) */}
            <div
              onMouseDown={(e) => e.stopPropagation()}
              className="absolute top-4 left-4 z-30 flex flex-col space-y-1.5 bg-white/95 backdrop-blur-md p-1.5 rounded-2xl shadow-xl border border-slate-200"
            >
              {/* Toggle Angles & Sliders Panel */}
              <button
                type="button"
                onClick={() => setShowAnglesPanel(!showAnglesPanel)}
                className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all cursor-pointer ${
                  showAnglesPanel
                    ? 'bg-slate-800 text-white shadow-sm'
                    : 'text-slate-600 hover:text-slate-900 hover:bg-slate-100'
                }`}
                title="Afficher/Masquer le panneau d'angles et curseurs"
              >
                <SlidersHorizontal className="w-4 h-4" />
              </button>

              {/* Auto-Orient Optimizer Tool */}
              <button
                type="button"
                onClick={handleAutoOrient}
                disabled={optimizing || !canRotate}
                className="w-9 h-9 rounded-xl flex items-center justify-center text-slate-600 hover:text-emerald-700 hover:bg-emerald-50 transition-all disabled:opacity-50 cursor-pointer"
                title="Orientation Automatique (Minimise les supports sans compter la base)"
              >
                <Wand2 className={`w-4 h-4 ${optimizing ? 'animate-spin text-emerald-600' : 'text-emerald-600'}`} />
              </button>

              {/* Reset to 0° Button */}
              <button
                type="button"
                onClick={onResetRotation}
                className="w-9 h-9 rounded-xl flex items-center justify-center text-slate-500 hover:text-rose-600 hover:bg-rose-50 transition-all cursor-pointer"
                title="Réinitialiser l'orientation à 0°"
              >
                <RotateCcw className="w-4 h-4" />
              </button>
            </div>

            {/* Camera navigation hint badge */}
            <div className="absolute bottom-4 left-4 z-20 bg-white/95 backdrop-blur-xs px-3.5 py-1.5 rounded-full border border-slate-200/90 shadow-sm flex items-center space-x-2 text-[11px] text-slate-600 font-medium pointer-events-none">
              <Compass className="w-3.5 h-3.5 text-slate-400" />
              <span>
                <strong>Clic gauche</strong> = Tourner la caméra • <strong>Clic droit</strong> = Translation • <strong>Molette</strong> = Zoom
              </span>
            </div>

            {/* Precise Rotation Adjustments Panel (Sliders + Numeric Input per Axis) */}
            {showAnglesPanel && !canRotate && (
              <div
                style={{ left: '4.5rem' }}
                onMouseDown={(e) => e.stopPropagation()}
                className="absolute top-4 z-40 bg-white/95 backdrop-blur-md p-3 rounded-2xl shadow-xl border border-slate-200 w-72 text-[11px] text-slate-600"
              >
                L'orientation n'est disponible que pour les fichiers STL. Le fichier est utilisé tel quel.
              </div>
            )}

            {showAnglesPanel && canRotate && (
              <div
                style={{ left: '4.5rem' }}
                onMouseDown={(e) => e.stopPropagation()}
                className="absolute top-4 z-40 bg-white/98 backdrop-blur-md p-3.5 rounded-2xl shadow-2xl border border-slate-200/95 w-80 animate-in fade-in slide-in-from-left-2 duration-150"
              >
                <div className="flex items-center justify-between pb-2 mb-2 border-b border-slate-100">
                  <span className="text-xs font-bold text-slate-800 flex items-center space-x-1.5">
                    <SlidersHorizontal className="w-3.5 h-3.5 text-primary-600" />
                    <span>Orientation du modèle</span>
                  </span>
                  <div className="flex items-center space-x-2">
                    <button
                      type="button"
                      onClick={onResetRotation}
                      className="text-[10px] font-bold text-slate-400 hover:text-rose-600 flex items-center space-x-1 transition-colors cursor-pointer"
                      title="Réinitialiser à 0°"
                    >
                      <RotateCcw className="w-3 h-3" />
                      <span>Reset</span>
                    </button>
                    <span className="text-slate-200">|</span>
                    <button
                      type="button"
                      onClick={handleAutoOrient}
                      disabled={optimizing}
                      className="text-[10px] font-bold text-emerald-600 hover:text-emerald-700 hover:underline flex items-center space-x-1 cursor-pointer"
                      title="Calculer l'orientation optimale"
                    >
                      <Sparkles className="w-3 h-3" />
                      <span>Auto</span>
                    </button>
                    <span className="text-slate-200">|</span>
                    <button
                      type="button"
                      onClick={() => setShowAnglesPanel(false)}
                      className="text-slate-400 hover:text-slate-700 p-0.5 rounded-md hover:bg-slate-100 transition-colors cursor-pointer"
                      title="Fermer le panneau"
                    >
                      <X className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>

                {/* X Axis (Pitch) */}
                <div className="mb-3">
                  <div className="flex justify-between items-center text-[11px] font-semibold text-slate-700 mb-1">
                    <span className="text-rose-600 font-bold">Axe X (Pitch)</span>
                    <div className="flex items-center space-x-1">
                      <input
                        type="number"
                        min="0"
                        max="360"
                        step="1"
                        value={rotateX}
                        onChange={(e) => handleManualAngleChange('x', e.target.value)}
                        className="w-14 px-1.5 py-0.5 text-[11px] font-mono font-bold text-slate-800 bg-slate-100 border border-slate-300 rounded text-right focus:bg-white focus:outline-none focus:border-rose-500"
                      />
                      <span className="text-[11px] font-bold text-slate-500">°</span>
                    </div>
                  </div>
                  <div className="flex items-center space-x-1.5">
                    <button
                      type="button"
                      onClick={() => stepRotate('x', -90)}
                      className="px-2 py-0.5 text-[10px] font-bold bg-slate-100 hover:bg-slate-200 rounded text-slate-700 cursor-pointer"
                    >
                      -90°
                    </button>
                    <input
                      type="range"
                      min="0"
                      max="360"
                      step="1"
                      value={rotateX}
                      onChange={(e) => onChangeRotateX(Number(e.target.value))}
                      className="flex-1 h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-rose-600"
                    />
                    <button
                      type="button"
                      onClick={() => stepRotate('x', 90)}
                      className="px-2 py-0.5 text-[10px] font-bold bg-slate-100 hover:bg-slate-200 rounded text-slate-700 cursor-pointer"
                    >
                      +90°
                    </button>
                  </div>
                </div>

                {/* Y Axis (Roll) */}
                <div className="mb-3">
                  <div className="flex justify-between items-center text-[11px] font-semibold text-slate-700 mb-1">
                    <span className="text-emerald-600 font-bold">Axe Y (Roll)</span>
                    <div className="flex items-center space-x-1">
                      <input
                        type="number"
                        min="0"
                        max="360"
                        step="1"
                        value={rotateY}
                        onChange={(e) => handleManualAngleChange('y', e.target.value)}
                        className="w-14 px-1.5 py-0.5 text-[11px] font-mono font-bold text-slate-800 bg-slate-100 border border-slate-300 rounded text-right focus:bg-white focus:outline-none focus:border-emerald-500"
                      />
                      <span className="text-[11px] font-bold text-slate-500">°</span>
                    </div>
                  </div>
                  <div className="flex items-center space-x-1.5">
                    <button
                      type="button"
                      onClick={() => stepRotate('y', -90)}
                      className="px-2 py-0.5 text-[10px] font-bold bg-slate-100 hover:bg-slate-200 rounded text-slate-700 cursor-pointer"
                    >
                      -90°
                    </button>
                    <input
                      type="range"
                      min="0"
                      max="360"
                      step="1"
                      value={rotateY}
                      onChange={(e) => onChangeRotateY(Number(e.target.value))}
                      className="flex-1 h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-emerald-600"
                    />
                    <button
                      type="button"
                      onClick={() => stepRotate('y', 90)}
                      className="px-2 py-0.5 text-[10px] font-bold bg-slate-100 hover:bg-slate-200 rounded text-slate-700 cursor-pointer"
                    >
                      +90°
                    </button>
                  </div>
                </div>

                {/* Z Axis (Yaw) */}
                <div>
                  <div className="flex justify-between items-center text-[11px] font-semibold text-slate-700 mb-1">
                    <span className="text-blue-600 font-bold">Axe Z (Yaw)</span>
                    <div className="flex items-center space-x-1">
                      <input
                        type="number"
                        min="0"
                        max="360"
                        step="1"
                        value={rotateZ}
                        onChange={(e) => handleManualAngleChange('z', e.target.value)}
                        className="w-14 px-1.5 py-0.5 text-[11px] font-mono font-bold text-slate-800 bg-slate-100 border border-slate-300 rounded text-right focus:bg-white focus:outline-none focus:border-blue-500"
                      />
                      <span className="text-[11px] font-bold text-slate-500">°</span>
                    </div>
                  </div>
                  <div className="flex items-center space-x-1.5">
                    <button
                      type="button"
                      onClick={() => stepRotate('z', -90)}
                      className="px-2 py-0.5 text-[10px] font-bold bg-slate-100 hover:bg-slate-200 rounded text-slate-700 cursor-pointer"
                    >
                      -90°
                    </button>
                    <input
                      type="range"
                      min="0"
                      max="360"
                      step="1"
                      value={rotateZ}
                      onChange={(e) => onChangeRotateZ(Number(e.target.value))}
                      className="flex-1 h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                    />
                    <button
                      type="button"
                      onClick={() => stepRotate('z', 90)}
                      className="px-2 py-0.5 text-[10px] font-bold bg-slate-100 hover:bg-slate-200 rounded text-slate-700 cursor-pointer"
                    >
                      +90°
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* Native Three.js WebGL Canvas Container */}
            <div
              ref={containerRef}
              className="w-full h-full relative"
              style={{ touchAction: 'none' }}
            />

            {/* Slicing loader overlay */}
            {loading && (
              <div className="absolute inset-0 bg-white/80 backdrop-blur-xs flex flex-col items-center justify-center z-30">
                <div className="w-10 h-10 border-3 border-primary-200 border-t-primary-600 rounded-full animate-spin mb-3"></div>
                <strong className="text-sm font-semibold text-slate-800">{t('slicingInProgress')}</strong>
                <span className="text-xs text-slate-500 mt-1">{t('slicingWait')}</span>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
