import React from 'react';
import { useTranslation } from 'react-i18next';
import { Disc3 } from 'lucide-react';
import { MATERIAL_DATA, getMaterialSpoolUrl } from '../data/printerVisuals';

export default function MaterialSelector({
  materials = [],
  selectedMaterialId,
  onSelectMaterial,
  filamentDensity,
  onChangeFilamentDensity,
  pricePerKg,
  onChangePricePerKg,
  disabled
}) {
  const { t } = useTranslation();

  const activeMaterial = materials.find((m) => m.id === selectedMaterialId) || materials[0];
  const activeMeta = MATERIAL_DATA[activeMaterial ? activeMaterial.id : 'pla'] || MATERIAL_DATA.pla;

  return (
    <div className="studio-card p-4 mb-3.5">
      {/* Header */}
      <div className="flex items-center justify-between mb-2.5">
        <div className="flex items-center space-x-2">
          <Disc3 className="w-4 h-4 text-slate-700" />
          <h2 className="text-xs sm:text-sm font-bold text-slate-900 tracking-tight">
            {t('filamentSettings')}
          </h2>
        </div>
        {activeMaterial && (
          <span className="text-[11px] font-mono font-medium text-slate-500 bg-slate-100 px-2 py-0.5 rounded-md border border-slate-200">
            Density: {activeMaterial.density} g/cm³
          </span>
        )}
      </div>

      {/* Material Spools Grid */}
      <div className="grid grid-cols-4 sm:grid-cols-7 gap-1.5 mb-2.5">
        {materials.map((mat) => {
          const isSelected = mat.id === selectedMaterialId;
          const meta = MATERIAL_DATA[mat.id] || MATERIAL_DATA.pla;
          return (
            <button
              key={mat.id}
              type="button"
              onClick={() => !disabled && onSelectMaterial(mat.id)}
              disabled={disabled}
              className={`p-1.5 rounded-xl border text-center transition-all flex flex-col items-center ${
                isSelected
                  ? 'bg-slate-50 border-primary-500 ring-2 ring-primary-500/20 shadow-xs'
                  : 'bg-white border-slate-200 hover:border-slate-300 hover:bg-slate-50/50'
              }`}
            >
              <div className="w-10 h-10 mb-0.5">
                <img
                  src={getMaterialSpoolUrl(mat.id)}
                  alt={meta.name}
                  className="w-full h-full object-contain"
                />
              </div>
              <span className="text-[11px] font-bold text-slate-800 block">
                {mat.id.toUpperCase()}
              </span>
              <span className="text-[9px] text-slate-400 block font-mono">
                {mat.density} g/cm³
              </span>
            </button>
          );
        })}
      </div>

      {/* Material Spotlight & Optional Overrides (Density & Cost) */}
      <div className="p-2.5 rounded-xl bg-slate-50 border border-slate-200/80">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2.5">
          <div className="flex-1">
            <div className="flex items-center space-x-2 mb-0.5">
              <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${activeMeta.badgeClass}`}>
                {activeMeta.name}
              </span>
              <span className="text-[11px] text-slate-500 font-medium">{activeMeta.fullName}</span>
            </div>
            <p className="text-[11px] text-slate-600 line-clamp-1 mb-0">
              {activeMeta.description}
            </p>
          </div>

          {/* Optional overrides: density & price per kg (empty by default) */}
          <div className="flex items-center space-x-2 shrink-0">
            <div>
              <label className="text-[10px] font-semibold text-slate-500 block mb-0.5">
                Density override (g/cm³)
              </label>
              <input
                type="number"
                step="0.01"
                min="0.5"
                max="5.0"
                className="w-20 px-2 py-1 text-xs rounded-md border border-slate-200 bg-white placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-primary-500"
                placeholder={activeMaterial ? `${activeMaterial.density}` : '1.24'}
                value={filamentDensity}
                onChange={(e) => onChangeFilamentDensity(e.target.value)}
                disabled={disabled}
                title="Leave empty to use standard material density"
              />
            </div>

            <div>
              <label className="text-[10px] font-semibold text-slate-500 block mb-0.5">
                Cost (€ / kg)
              </label>
              <input
                type="number"
                step="1"
                min="0"
                className="w-16 px-2 py-1 text-xs rounded-md border border-slate-200 bg-white placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-primary-500"
                placeholder="20.0"
                value={pricePerKg}
                onChange={(e) => onChangePricePerKg(e.target.value)}
                disabled={disabled}
                title={t('pricePerKgHelp')}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
