import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { KeyRound, Eye, EyeOff, X, ArrowRight, Check } from 'lucide-react';

export default function ApiKeyModal({
  show,
  apiKey,
  onSave,
  onHide
}) {
  const { t } = useTranslation();
  const [keyInput, setKeyInput] = useState(apiKey || '');
  const [showKey, setShowKey] = useState(false);

  React.useEffect(() => {
    setKeyInput(apiKey || '');
  }, [apiKey, show]);

  if (!show) return null;

  const handleSubmit = (e) => {
    e.preventDefault();
    onSave(keyInput.trim());
    onHide();
  };

  const handleClear = () => {
    setKeyInput('');
    onSave('');
    onHide();
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-900/40 backdrop-blur-xs flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-200 w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-150">
        <form onSubmit={handleSubmit}>
          {/* Header */}
          <div className="flex items-center justify-between px-5 py-3.5 border-b border-slate-100 bg-slate-50/50">
            <div className="flex items-center space-x-2">
              <div className="w-6 h-6 rounded-md bg-primary-100 text-primary-700 font-bold flex items-center justify-center">
                <KeyRound className="w-3.5 h-3.5 text-primary-700" />
              </div>
              <h2 className="text-xs sm:text-sm font-bold text-slate-900">
                {t('apiKeyModalTitle')}
              </h2>
            </div>
            <button
              type="button"
              onClick={onHide}
              className="text-slate-400 hover:text-slate-600 rounded-lg p-1 text-sm"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Body */}
          <div className="p-5">
            <p className="text-xs text-slate-500 mb-3 leading-relaxed">
              {t('apiKeyModalDesc')}
            </p>

            <div className="mb-3">
              <label className="text-[11px] font-semibold text-slate-700 block mb-1">
                X-RapidAPI-Key
              </label>
              <div className="relative flex items-center">
                <input
                  type={showKey ? 'text' : 'password'}
                  placeholder={t('apiKeyPlaceholder')}
                  value={keyInput}
                  onChange={(e) => setKeyInput(e.target.value)}
                  autoFocus
                  className="w-full pl-3 pr-10 py-2 text-xs font-mono rounded-lg border border-slate-200 bg-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-primary-500"
                />
                <button
                  type="button"
                  onClick={() => setShowKey(!showKey)}
                  className="absolute right-2 text-slate-400 hover:text-slate-600 p-1"
                  title={showKey ? 'Hide' : 'Show'}
                >
                  {showKey ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
              <div className="flex justify-between items-center mt-2">
                <a
                  href="https://rapidapi.com/Thomx/api/3d-print-stl-estimation"
                  target="_blank"
                  rel="noreferrer"
                  className="text-[11px] text-primary-600 hover:underline inline-flex items-center space-x-1"
                >
                  <span>{t('apiKeyHelp')}</span>
                  <ArrowRight className="w-3 h-3" />
                </a>

                {apiKey && (
                  <button
                    type="button"
                    onClick={handleClear}
                    className="text-[11px] text-red-500 hover:underline"
                  >
                    Remove key
                  </button>
                )}
              </div>
            </div>
          </div>

          {/* Footer */}
          <div className="px-5 py-3 bg-slate-50 border-t border-slate-100 flex items-center justify-end space-x-2">
            <button
              type="button"
              onClick={onHide}
              className="px-3 py-1.5 rounded-lg text-xs font-semibold text-slate-600 hover:text-slate-900"
            >
              {t('cancel')}
            </button>
            <button
              type="submit"
              className="inline-flex items-center space-x-1 px-4 py-1.5 rounded-lg text-xs font-semibold bg-primary-600 hover:bg-primary-700 text-white shadow-xs"
            >
              <Check className="w-3.5 h-3.5" />
              <span>{t('save')}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
