import './App.css';

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { Store, ReactNotifications } from 'react-notifications-component';
import 'react-notifications-component/dist/theme.css';
import { Zap, AlertTriangle } from 'lucide-react';

import {
  getStoredSettings,
  saveStoredSettings,
  getStoredApiKey,
  saveStoredApiKey,
  hasCompletedWizard,
  markWizardCompleted,
  fetchPresetsCatalog,
  calculateEstimate
} from './services/api';

import Header from './components/Header';
import StudioModelViewer from './components/StudioModelViewer';
import PrinterSelector from './components/PrinterSelector';
import MaterialSelector from './components/MaterialSelector';
import QualityAndOptions from './components/QualityAndOptions';
import EstimateResultCard from './components/EstimateResultCard';
import OversizeModal from './components/OversizeModal';
import WizardModal from './components/WizardModal';
import ApiKeyModal from './components/ApiKeyModal';
import { exceedsBuildVolume } from './services/estimateDetails';
import { PrintablesLogo, MakerWorldLogo, ThingiverseLogo } from './components/ModelRepoLogos';

export default function App() {
  const { t, i18n } = useTranslation();

  // Browser tab title and <html lang> follow the selected language
  useEffect(() => {
    document.title = t('appName');
    document.documentElement.lang = (i18n.resolvedLanguage || i18n.language || 'en').split('-')[0];
  }, [t, i18n.language, i18n.resolvedLanguage]);

  // Mode URL query params: ?hosted (same origin API, hide key UI), ?simple (kofi order button)
  const urlParams = useMemo(() => new URLSearchParams(window.location.search), []);
  const isHosted = urlParams.get('hosted') !== null;
  const isSimple = urlParams.get('simple') !== null;

  // Catalog State
  const [catalog, setCatalog] = useState({ printers: [], materials: [] });

  // Persistent User Preferences
  const [settings, setSettings] = useState(getStoredSettings);
  const [apiKey, setApiKey] = useState(getStoredApiKey);

  // File & Calculation State
  const [selectedFile, setSelectedFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [modelDims, setModelDims] = useState(null); // oriented size on the plate (mm)
  const [showOversize, setShowOversize] = useState(false);

  // Modals
  const [showWizard, setShowWizard] = useState(false);
  const [showApiKeyModal, setShowApiKeyModal] = useState(false);

  // Load Presets Catalog
  useEffect(() => {
    fetchPresetsCatalog(isHosted).then((data) => {
      if (data && data.printers) {
        setCatalog(data);
      }
    });
  }, [isHosted]);

  // Launch Wizard for First-Time User
  useEffect(() => {
    if (!hasCompletedWizard()) {
      setShowWizard(true);
    }
  }, []);

  // Update Settings Partial & Persist
  const updateSettings = useCallback((partial) => {
    setSettings((prev) => {
      const next = { ...prev, ...partial };
      saveStoredSettings(next);
      return next;
    });
  }, []);

  const handleSaveApiKey = useCallback((newKey) => {
    setApiKey(newKey);
    saveStoredApiKey(newKey);
    if (newKey) {
      Store.addNotification({
        title: t('apiKeyConfigured'),
        message: t('apiKeySavedNotice'),
        type: 'success',
        insert: 'top',
        container: 'top-center',
        dismiss: { duration: 3000, onScreen: true }
      });
    }
  }, [t]);

  const handleCloseWizard = useCallback(() => {
    markWizardCompleted();
    setShowWizard(false);
  }, []);

  // Selected Printer Object
  const selectedPrinter = useMemo(() => {
    return catalog.printers.find((p) => p.id === settings.printerId) || catalog.printers[0];
  }, [catalog.printers, settings.printerId]);

  // Handle STL file dropped/selected
  const handleFileAccepted = useCallback((files) => {
    if (files && files[0]) {
      setSelectedFile(files[0]);
      setResult(null);
    }
  }, []);

  const selectedMaterial = useMemo(() => {
    return catalog.materials.find((m) => m.id === settings.materialId) || null;
  }, [catalog.materials, settings.materialId]);

  const isOversize = exceedsBuildVolume(modelDims, selectedPrinter && selectedPrinter.bedSize);

  // Entry point of the button: warn first when the model does not fit the build volume
  const handleEstimateClick = () => {
    if (selectedFile && isOversize) {
      setShowOversize(true);
      return;
    }
    handleEstimate();
  };

  // Trigger Slicing Estimate Request
  const handleEstimate = async () => {
    setShowOversize(false);
    if (!selectedFile) {
      Store.addNotification({
        title: t('warningTitle'),
        message: t('plzSelectModel'),
        type: 'warning',
        insert: 'top',
        container: 'top-center',
        dismiss: { duration: 4000, onScreen: true }
      });
      return;
    }

    // If public mode and no API key is set yet, prompt the user now
    if (!isHosted && !apiKey) {
      setShowApiKeyModal(true);
      Store.addNotification({
        title: t('warningTitle'),
        message: t('plzEnterApiKey'),
        type: 'warning',
        insert: 'top',
        container: 'top-center',
        dismiss: { duration: 5000, onScreen: true }
      });
      return;
    }

    setLoading(true);
    try {
      const data = await calculateEstimate(selectedFile, settings, { isHosted, apiKey });
      // Snapshot of what was sent, so the detailed result stays consistent if settings change later
      setResult({
        data,
        context: {
          file: selectedFile,
          settings: { ...settings },
          printer: selectedPrinter,
          material: selectedMaterial,
          modelDims,
          createdAt: new Date().toISOString()
        }
      });
    } catch (err) {
      console.error('Estimate failed', err);
      const errMsg = err.response && err.response.data && err.response.data.detail
        ? err.response.data.detail
        : (err.message || t('sliceFailed'));

      Store.addNotification({
        title: t('errorTitle'),
        message: errMsg,
        type: 'danger',
        insert: 'top',
        container: 'top-center',
        dismiss: { duration: 6000, onScreen: true }
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 flex flex-col font-sans">
      <ReactNotifications />

      {/* Top Navbar */}
      <Header
        isHosted={isHosted}
        hasApiKey={Boolean(apiKey)}
        onOpenApiKeyModal={() => setShowApiKeyModal(true)}
        onOpenWizard={() => setShowWizard(true)}
      />

      {/* Main Studio Full-Width Layout: 3D Viewport in the Center / Dominant */}
      <main className="w-full px-3 sm:px-6 py-4 flex-1 flex flex-col">
        <div className="w-full flex-1 grid grid-cols-1 lg:grid-cols-12 gap-4 sm:gap-6 items-stretch">
          
          {/* Main 3D Viewport with Integrated Studio Tool Palette & Results (7 cols on Desktop, Full Height) */}
          <div className="lg:col-span-7 xl:col-span-8 flex flex-col h-full space-y-4">
            <div className="flex-1 min-h-[480px] flex flex-col">
              <StudioModelViewer
                file={selectedFile}
                onFileAccepted={handleFileAccepted}
                printerBedSize={selectedPrinter ? selectedPrinter.bedSize : [220, 220, 250]}
                rotateX={settings.rotateX}
                rotateY={settings.rotateY}
                rotateZ={settings.rotateZ}
                onChangeRotateX={(x) => updateSettings({ rotateX: x })}
                onChangeRotateY={(y) => updateSettings({ rotateY: y })}
                onChangeRotateZ={(z) => updateSettings({ rotateZ: z })}
                onResetRotation={() => updateSettings({ rotateX: 0, rotateY: 0, rotateZ: 0 })}
                onModelDimsChange={setModelDims}
                loading={loading}
              />
            </div>

            {/* Calculation Estimate Results */}
            {result && !loading && (
              <EstimateResultCard
                result={result.data}
                context={result.context}
                onRecalculate={handleEstimate}
                isSimple={isSimple}
              />
            )}
          </div>

          {/* Right Parameters Sidebar (5 cols on Desktop, scrollable) */}
          <div className="lg:col-span-5 xl:col-span-4 flex flex-col justify-between">
            <div>
              {/* 1. Printer Preset Selector */}
              <PrinterSelector
                printers={catalog.printers}
                selectedPrinterId={settings.printerId}
                onSelectPrinter={(id) => updateSettings({ printerId: id })}
                disabled={loading}
              />

              {/* 2. Material Preset Selector */}
              <MaterialSelector
                materials={catalog.materials}
                selectedMaterialId={settings.materialId}
                onSelectMaterial={(id) => updateSettings({ materialId: id })}
                filamentDensity={settings.filamentDensity}
                onChangeFilamentDensity={(d) => updateSettings({ filamentDensity: d })}
                pricePerKg={settings.pricePerKg}
                onChangePricePerKg={(p) => updateSettings({ pricePerKg: p })}
                disabled={loading}
              />

              {/* 3. Quality & Slicing Options */}
              <QualityAndOptions
                selectedPrinter={selectedPrinter}
                quality={settings.quality}
                onChangeQuality={(q) => updateSettings({ quality: q })}
                layerHeight={settings.layerHeight}
                onChangeLayerHeight={(lh) => updateSettings({ layerHeight: lh })}
                infill={settings.infill}
                onChangeInfill={(inf) => updateSettings({ infill: inf })}
                support={settings.support}
                onChangeSupport={(sup) => updateSettings({ support: sup })}
                speed={settings.speed}
                onChangeSpeed={(spd) => updateSettings({ speed: spd })}
                acceleration={settings.acceleration}
                onChangeAcceleration={(acc) => updateSettings({ acceleration: acc })}
                disabled={loading}
              />

              {/* 4. Action Button: Slice & Estimate */}
              <button
                type="button"
                onClick={handleEstimateClick}
                disabled={loading || !selectedFile}
                className="w-full py-3.5 px-4 rounded-xl font-bold text-sm text-white bg-primary-600 hover:bg-primary-700 active:bg-primary-800 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm hover:shadow transition-all flex items-center justify-center space-x-2"
              >
                {loading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    <span>{t('slicingInProgress')}</span>
                  </>
                ) : (
                  <>
                    <Zap className="w-4 h-4 fill-white" />
                    <span>{t('sliceAndEstimate')}</span>
                  </>
                )}
              </button>
              {isOversize && !loading && (
                <p className="mt-2 flex items-start space-x-1.5 text-[11px] font-medium text-rose-600">
                  <AlertTriangle className="w-3.5 h-3.5 shrink-0 mt-px" />
                  <span>{t('oversizeInline')}</span>
                </p>
              )}
            </div>

            {/* Authentic 3D Model Libraries Footer */}
            <div className="mt-4 pt-3 border-t border-slate-200/80 text-center">
              <span className="text-[11px] text-slate-400 block mb-2 font-medium">
                {t('modelLibraries')}
              </span>
              <div className="flex items-center justify-center space-x-2 flex-wrap gap-y-1.5">
                <a
                  href="https://www.printables.com/"
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg text-xs font-semibold text-slate-700 bg-white hover:bg-slate-50 border border-slate-200 shadow-2xs"
                  title="Printables by Prusa"
                >
                  <PrintablesLogo className="w-4 h-4 shrink-0" />
                  <span>Printables</span>
                </a>
                <a
                  href="https://makerworld.com/"
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg text-xs font-semibold text-slate-700 bg-white hover:bg-slate-50 border border-slate-200 shadow-2xs"
                  title="MakerWorld by Bambu Lab"
                >
                  <MakerWorldLogo className="w-4 h-4 shrink-0" />
                  <span>MakerWorld</span>
                </a>
                <a
                  href="https://www.thingiverse.com/"
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg text-xs font-semibold text-slate-700 bg-white hover:bg-slate-50 border border-slate-200 shadow-2xs"
                  title="Thingiverse"
                >
                  <ThingiverseLogo className="w-4 h-4 shrink-0" />
                  <span>Thingiverse</span>
                </a>
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* Onboarding Wizard Modal */}
      <WizardModal
        show={showWizard}
        onClose={handleCloseWizard}
        printers={catalog.printers}
        materials={catalog.materials}
        selectedPrinterId={settings.printerId}
        onSelectPrinter={(id) => updateSettings({ printerId: id })}
        selectedMaterialId={settings.materialId}
        onSelectMaterial={(id) => updateSettings({ materialId: id })}
        apiKey={apiKey}
        onSaveApiKey={handleSaveApiKey}
        isHosted={isHosted}
      />

      <OversizeModal
        show={showOversize}
        modelDims={modelDims}
        printer={selectedPrinter}
        onCancel={() => setShowOversize(false)}
        onConfirm={handleEstimate}
      />

      {/* RapidAPI Key Modal */}
      <ApiKeyModal
        show={showApiKeyModal}
        apiKey={apiKey}
        onSave={handleSaveApiKey}
        onHide={() => setShowApiKeyModal(false)}
      />
    </div>
  );
}
